#define BEATMOVE 1

const float FREQ_RANGE = 64.0;
const float PI = 3.1415;
const float RADIUS = 0.6;
const float BRIGHTNESS = 0.2;
const float SPEED = 0.5;

// Convertir HSV a RGB
vec3 hsv2rgb(vec3 c){
    vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
    vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
    return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

float luma(vec3 color) {
    return dot(color, vec3(0.0, 0.0, 0.0));
}

float getfrequency(float x) {
    return texture(iChannel0, vec2(floor(x * FREQ_RANGE + 1.2) / FREQ_RANGE, 0.25)).x + 0.01;
}

float getfrequency_smooth(float x) {
    float index = floor(x * FREQ_RANGE) / FREQ_RANGE;
    float next = floor(x * FREQ_RANGE + 1.0) / FREQ_RANGE;
    return mix(getfrequency(index), getfrequency(next), smoothstep(0.1, 1.0, fract(x * FREQ_RANGE)));
}

float getfrequency_blend(float x) {
    return mix(getfrequency(x), getfrequency_smooth(x), 0.5);
}

// Función modificada para el halo
vec3 doHalo(vec2 fragment, float radius, float x) {
    float dist = length(fragment);
    float ring = 2.0 / abs(dist - radius);

    float b = dist < radius ? BRIGHTNESS * 0.3 : BRIGHTNESS;

    vec3 col = vec3(0.0);

    // Usamos el mismo color de la línea para el halo
    col += hsv2rgb(vec3(x * 0.1 + iTime * 0.1, 1.0, 1.2)) * ring * b;

    // Efecto de frecuencia aguda
    float freq = max(getfrequency_blend(abs(atan(fragment.x, fragment.y) / PI)) - 0.001, 0.0);
    col *= pow(freq, 3.0);  // Aumenta la intensidad en frecuencias agudas

    // Efecto de frecuencia grave
    float lowFreq = getfrequency(abs(atan(fragment.x, fragment.y) / PI * 0.5)); // Baja frecuencia
    col *= smoothstep(0.0, 0.5, lowFreq); // Suaviza el efecto de frecuencias graves

    // Reducción del halo negro
    col *= smoothstep(radius * 0.5, radius, dist);

    return col;
}

// Función modificada para la línea
vec3 doLine(vec2 fragment, float radius, float x) {
    vec3 col = hsv2rgb(vec3(x * 0.1 + iTime * 0.1, 1.0, 1.2));

    float freq = abs(fragment.x * 0.02);

    // Control de frecuencias agudas y graves para el brillo y difusión
    float highFreq = getfrequency_smooth(freq); // Alta frecuencia
    col *= (1.0 / abs(fragment.y)) * BRIGHTNESS * highFreq;

    // Baja frecuencia
    float lowFreq = getfrequency(freq * 0.5); // Baja frecuencia
    col *= smoothstep(radius, radius * 0.01, abs(fragment.x)) * lowFreq * 0.5;

    return col;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 fragPos = fragCoord / iResolution.xy;
    fragPos = (fragPos - 0.5) * 2.0;
    fragPos.x *= iResolution.x / iResolution.y;

    vec3 color = vec3(0.0, 0.0, 0.0);

    // Pasamos la coordenada x para un valor consistente en ambas funciones
    float x = fragPos.x; 

    // Añadir color con el mismo tono para el halo
    color += doHalo(fragPos, RADIUS, x);

    // Fijar la rotación a 90 grados (PI / 2 radianes)
    float angle = 90.0; // Ángulo fijo de 90 grados
    float c = cos(radians(angle)); // Coseno de 90 grados
    float s = sin(radians(angle)); // Seno de 90 grados

    // Aplicar la rotación fija de 90 grados
    vec2 rot = mat2(c, s, -s, c) * fragPos;

    // Añadir color para la línea
    color += doLine(rot, RADIUS, rot.x);

    // Asegurar que la luz negra no opaque la luz
    color += max(luma(color) - 1.0, 0.0);

    fragColor = vec4(color, 1.0);
}
